const $=id=>document.getElementById(id),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};let data={};try{data=JSON.parse(localStorage.getItem('pocket-v1')||'{}')}catch{}let filter='all',editing=null;const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n),categories={expense:['Food & groceries','Rent & home','Shopping','Transport','Bills & utilities','Health','Entertainment','Other'],investment:['Mutual funds','Stocks','Fixed deposit','Gold','Retirement','Other']};$('month').value=today().slice(0,7);const current=()=>data[$('month').value]||{salary:0,received:'',entries:[]};function save(){try{localStorage.setItem('pocket-v1',JSON.stringify(data));return true}catch{toast('Storage is unavailable. Export your data before leaving.');return false}}function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3000)}function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function dateText(d){return new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}function render(){const m=current(),expenses=m.entries.filter(e=>e.type==='expense'),investments=m.entries.filter(e=>e.type==='investment'),e=expenses.reduce((a,b)=>a+b.amount,0),i=investments.reduce((a,b)=>a+b.amount,0),left=m.salary-e-i;$('incomeTotal').textContent=money(m.salary);$('expenseTotal').textContent=money(e);$('investTotal').textContent=money(i);$('remaining').textContent=money(left);$('salary').value=m.salary||'';$('received').value=m.received||$('month').value+'-01';$('payDate').textContent=m.received?'Received on '+dateText(m.received):'Add your monthly salary';$('expenseCount').textContent=expenses.length+' transactions this month';$('investCount').textContent=investments.length+' investments this month';$('count').textContent=m.entries.length;$('entryTotal').textContent=m.entries.length+' entries';$('balanceNote').textContent=left<0?'Your outgoings exceed your salary.':m.salary?'A little breathing room for your next big thing.':'Your fresh start begins here.';$('balanceNote').style.color=left<0?'#ffc4b1':'';let pct=n=>m.salary?Math.round(n/m.salary*100):0;$('expensePercent').textContent=pct(e)+'%';$('investPercent').textContent=pct(i)+'%';$('savePercent').textContent=pct(left)+'%';const denominator=Math.max(m.salary,e+i,1);$('allocation').innerHTML=`<i style="width:${e/denominator*100}%;background:#e4b89b"></i><i style="width:${i/denominator*100}%;background:#b8acd4"></i><i style="width:${Math.max(left,0)/denominator*100}%;background:#a7bf80"></i>`;$('insight').textContent=left<0?'↗ Over salary by '+money(-left):m.salary?'✦ '+pct(left+i)+'% of your salary is saved or invested.':'✦ Small steps. Stronger savings.';const list=m.entries.filter(e=>filter==='all'||e.type===filter).sort((a,b)=>b.date.localeCompare(a.date));$('transactions').innerHTML=list.length?list.map(e=>`<div class="row"><div class="rowMain"><span class="icon ${e.type==='expense'?'peach':'purple'}">${e.type==='expense'?'↗':'⌁'}</span><div><div class="rowTitle">${escapeHTML(e.name)}</div><div class="rowCategory">${escapeHTML(e.category)}</div></div></div><div class="rowDate">${dateText(e.date)}</div><div class="rowAmount">−${money(e.amount)}<div class="rowActions"><button data-edit="${e.id}">Edit</button><button data-delete="${e.id}">Delete</button></div></div></div>`).join(''):`<div class="empty"><div class="emptyIcon">≋</div><h3>${filter==='all'?'A fresh page for your finances':'No '+(filter==='expense'?'expenses':'investments')+' yet'}</h3><p>Add your ${filter==='investment'?'first investment':'everyday expenses and investments'} to see your month come together.</p></div>`}
$('salaryForm').onsubmit=e=>{e.preventDefault();const month=$('month').value;if(!$('received').value.startsWith(month)){toast('Choose a salary date within the selected month.');return}const m=current();data[month]={...m,salary:Number($('salary').value),received:$('received').value};const ok=save();render();$('salaryFeedback').textContent=ok?'✓ Salary saved for this month':''};$('month').onchange=()=>{if(!$('month').value)$('month').value=today().slice(0,7);$('salaryFeedback').textContent='';render()};function shift(n){let [y,m]=$('month').value.split('-').map(Number),d=new Date(y,m-1+n,1);$('month').value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;$('month').onchange()}$('prev').onclick=()=>shift(-1);$('next').onclick=()=>shift(1);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});function setCategories(){const options=categories[$('type').value];$('category').replaceChildren(...options.map(x=>new Option(x,x)))}$('type').onchange=setCategories;function openEntry(entry){editing=entry?.id||null;$('entryForm').reset();$('type').value=entry?.type||'expense';setCategories();$('name').value=entry?.name||'';$('amount').value=entry?.amount||'';$('date').value=entry?.date||(today().startsWith($('month').value)?today():$('month').value+'-01');if(entry)$('category').value=entry.category;$('dialogTitle').textContent=entry?'Edit transaction':'Add a transaction';$('dialog').showModal()}$('add').onclick=()=>openEntry();$('close').onclick=()=>$('dialog').close();$('entryForm').onsubmit=e=>{e.preventDefault();if(!$('date').value.startsWith($('month').value)){toast('Choose a transaction date within the selected month.');return}if(!$('name').value.trim()){toast('Add a transaction name.');return}const m=current(),entry={id:editing||crypto.randomUUID(),name:$('name').value.trim(),amount:Number($('amount').value),type:$('type').value,date:$('date').value,category:$('category').value};m.entries=editing?m.entries.map(x=>x.id===editing?entry:x):[...m.entries,entry];data[$('month').value]=m;const ok=save();$('dialog').close();render();if(ok)toast(editing?'Transaction updated':'Transaction added')};$('transactions').onclick=e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit)openEntry(current().entries.find(x=>x.id===edit));if(del&&confirm('Delete this transaction?')){const m=current();m.entries=m.entries.filter(x=>x.id!==del);data[$('month').value]=m;save();render()}};$('export').onclick=()=>{const m=current(),rows=[['Type','Description','Category','Date','Amount (INR)'],['Income','Monthly salary','Salary',m.received,m.salary],...m.entries.map(e=>[e.type,e.name,e.category,e.date,e.amount])],csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='pocket-'+$('month').value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();
